import{_ as a,C as r,o as n,c as o,a2 as e,b as g,w as h,a as c,E as l,a3 as s}from"./chunks/framework.2Es64uX1.js";const b=JSON.parse('{"title":"CHƯƠNG 0: LỜI NÓI ĐẦU VÀ ĐỊNH VỊ CASE STUDY XUYÊN SUỐT","description":"","frontmatter":{},"headers":[],"relativePath":"ch00_loi_noi_dau.md","filePath":"ch00_loi_noi_dau.md"}'),u={name:"ch00_loi_noi_dau.md"};function d(m,t,p,C,y,A){const i=r("Mermaid");return n(),o("div",null,[t[1]||(t[1]=e('<h1 id="chuong-0-loi-noi-đau-va-đinh-vi-case-study-xuyen-suot" tabindex="-1">CHƯƠNG 0: LỜI NÓI ĐẦU VÀ ĐỊNH VỊ CASE STUDY XUYÊN SUỐT <a class="header-anchor" href="#chuong-0-loi-noi-đau-va-đinh-vi-case-study-xuyen-suot" aria-label="Permalink to &quot;CHƯƠNG 0: LỜI NÓI ĐẦU VÀ ĐỊNH VỊ CASE STUDY XUYÊN SUỐT&quot;">​</a></h1><h2 id="preface-overarching-real-world-case-study" tabindex="-1">(PREFACE &amp; OVERARCHING REAL-WORLD CASE STUDY) <a class="header-anchor" href="#preface-overarching-real-world-case-study" aria-label="Permalink to &quot;(PREFACE &amp; OVERARCHING REAL-WORLD CASE STUDY)&quot;">​</a></h2><blockquote><p><em>&quot;Writing code is easy; building and maintaining software systems that survive the test of time, business pivots, and architectural evolution is engineering.&quot;</em><br> — Lời tựa phỏng theo Titus Winters et al., <em>Software Engineering at Google</em> [@winters2020software]</p></blockquote><hr><h2 id="_1-boi-canh-va-triet-ly-tiep-can" tabindex="-1">1. BỐI CẢNH VÀ TRIẾT LÝ TIẾP CẬN <a class="header-anchor" href="#_1-boi-canh-va-triet-ly-tiep-can" aria-label="Permalink to &quot;1. BỐI CẢNH VÀ TRIẾT LÝ TIẾP CẬN&quot;">​</a></h2><h3 id="_1-1-su-chuyen-dich-lich-su-cua-nganh-phan-mem" tabindex="-1">1.1. Sự Chuyển Dịch Lịch Sử Của Ngành Phần Mềm <a class="header-anchor" href="#_1-1-su-chuyen-dich-lich-su-cua-nganh-phan-mem" aria-label="Permalink to &quot;1.1. Sự Chuyển Dịch Lịch Sử Của Ngành Phần Mềm&quot;">​</a></h3><p>Trong nhiều thập kỷ, việc đào tạo kỹ thuật phần mềm truyền thống thường tách biệt giữa lý thuyết mô hình hóa (như thác nước, ca sử dụng hình thức) và lập trình thực tế. Sinh viên và lập trình viên mới vào nghề thường lầm tưởng rằng &quot;lập trình giỏi&quot; đồng nghĩa với &quot;kỹ thuật phần mềm xuất sắc&quot;.</p><p>Tuy nhiên, khi bước vào kỷ nguyên của hệ thống phân tán quy mô lớn, điện toán đám mây (Cloud-Native), văn hóa DevOps/DevSecOps và đặc biệt là sự bùng nổ của Trí tuệ nhân tạo (AI-Assisted Engineering) [@huyen2025aiengineering], ranh giới giữa viết mã đơn thuần và công nghệ phần mềm thực thụ trở nên rõ nét hơn bao giờ hết:</p><ul><li><strong>Lập trình (Programming):</strong> Tập trung vào việc tạo ra đoạn mã đúng cú pháp, chạy được và giải quyết bài toán thuật toán tại một thời điểm tức thời.</li><li><strong>Kỹ thuật Phần mềm Ứng dụng (Applied Software Engineering):</strong> Là nghệ thuật và khoa học quản trị mã nguồn <strong>qua trục thời gian (over time)</strong> [@winters2020software], quản trị sự thay đổi liên tục của yêu cầu nghiệp vụ, bảo đảm tính sẵn sàng cao, bảo mật dịch trái (Shift-Left Security), và duy trì khả năng bảo trì khi hệ thống tăng trưởng gấp hàng trăm lần.</li></ul><p>Cuốn sách tham khảo này được biên soạn nhằm lấp đầy khoảng trống giữa lý thuyết giảng đường đại học và thực tế công nghiệp khắt khe. Cuốn sách không dừng lại ở việc định nghĩa khái niệm, mà cung cấp các mẫu thiết kế, quy chuẩn kiến trúc và công nghệ hiện đại nhất đang định hình các doanh nghiệp công nghệ hàng đầu thế giới.</p><hr><h2 id="_2-đoi-tuong-đoc-gia-va-khung-nang-luc-đat-đuoc" tabindex="-1">2. ĐỐI TƯỢNG ĐỘC GIẢ VÀ KHUNG NĂNG LỰC ĐẠT ĐƯỢC <a class="header-anchor" href="#_2-đoi-tuong-đoc-gia-va-khung-nang-luc-đat-đuoc" aria-label="Permalink to &quot;2. ĐỐI TƯỢNG ĐỘC GIẢ VÀ KHUNG NĂNG LỰC ĐẠT ĐƯỢC&quot;">​</a></h2><p>Cuốn sách được thiết kế chuyên sâu dành cho:</p><ol><li><strong>Sinh viên và Học viên Cao học ngành CNTT, ĐVT, Hệ thống Thông tin:</strong> Cần tài liệu tham khảo để thực hiện Đồ án tốt nghiệp, Luận văn thạc sĩ và chuẩn bị phỏng vấn kiến trúc phần mềm tại các tập đoàn công nghệ.</li><li><strong>Kỹ sư Phần mềm (Software Engineers / Fullstack Developers):</strong> Muốn vượt qua giới hạn &quot;thợ gõ code&quot; (Coder) để tiến lên vai trò <strong>Software Architect</strong>, <strong>Tech Lead</strong> hoặc <strong>DevOps/SRE Specialist</strong>.</li><li><strong>Giảng viên Đại học:</strong> Dùng làm tài liệu tham khảo chính yếu cho học phần <em>Kỹ thuật Phần mềm Nâng cao</em>, <em>Kiến trúc Phần mềm</em>, hoặc <em>Phát triển Phần mềm Doanh nghiệp</em>.</li></ol><h3 id="khung-nang-luc-cot-loi-learning-outcomes-matrix" tabindex="-1">Khung Năng Lực Cốt Lõi (Learning Outcomes Matrix) <a class="header-anchor" href="#khung-nang-luc-cot-loi-learning-outcomes-matrix" aria-label="Permalink to &quot;Khung Năng Lực Cốt Lõi (Learning Outcomes Matrix)&quot;">​</a></h3><p>Sau khi nghiên cứu và thực hành trọn vẹn cuốn sách, độc giả sẽ làm chủ 5 nhóm năng lực:</p><ul><li><strong>Kiến trúc &amp; Thiết kế:</strong> Thành thạo mô hình hóa C4, nới lỏng phụ thuộc qua Clean Architecture [@martin2017cleanarch], thiết kế Microservices và Event-Driven Architecture (EDA) [@newman2021building].</li><li><strong>Chất lượng Mã nguồn:</strong> Nắm vững nguyên lý SOLID, phát hiện Code Smells và thực hành Refactoring an toàn có bảo trợ của kiểm thử tự động [@fowler2018refactoring].</li><li><strong>Vận hành &amp; Tự động hóa:</strong> Tự tay thiết lập luồng CI/CD với GitHub Actions, container hóa bằng Docker/Kubernetes, đo lường năng lực đội ngũ bằng 4 chỉ số DORA [@kim2016devopshandbook].</li><li><strong>Quản trị Dữ liệu Lớn:</strong> Thiết kế API REST/gRPC/GraphQL chuẩn mực, tối ưu hóa Caching đa tầng và xử lý giao dịch phân tán bằng Saga Pattern [@kleppmann2017designing].</li><li><strong>Tăng cường AI (AI-Augmented):</strong> Tích hợp hiệu quả các công cụ lập trình tạo sinh (LLM, Copilot, Claude Code) vào SDLC và triển khai mô hình học máy vào thực tế (MLOps) [@huyen2022designing].</li></ul><hr><h2 id="_3-case-study-thuc-chien-xuyen-suot-he-sinh-thai-y-te-so-dr-may-day-v2-0" tabindex="-1">3. CASE STUDY THỰC CHIẾN XUYÊN SUỐT: HỆ SINH THÁI Y TẾ SỐ DR MAY DAY v2.0 <a class="header-anchor" href="#_3-case-study-thuc-chien-xuyen-suot-he-sinh-thai-y-te-so-dr-may-day-v2-0" aria-label="Permalink to &quot;3. CASE STUDY THỰC CHIẾN XUYÊN SUỐT: HỆ SINH THÁI Y TẾ SỐ DR MAY DAY v2.0&quot;">​</a></h2><p>Để tránh biến cuốn sách thành tập hợp các ví dụ đồ chơi (toy examples) rời rạc, cuốn sách áp dụng phương pháp <strong>Học tập qua Dự án Thực chiến (Project-Based Learning)</strong> bằng cách đưa một hệ thống lớn xuyên suốt qua tất cả các chương: <strong>Hệ sinh thái Y tế số Thông minh Dr May Day v2.0</strong>.</p><h3 id="_3-1-boi-canh-bai-toan-nghiep-vu-problem-statement" tabindex="-1">3.1. Bối Cảnh Bài Toán Nghiệp Vụ (Problem Statement) <a class="header-anchor" href="#_3-1-boi-canh-bai-toan-nghiep-vu-problem-statement" aria-label="Permalink to &quot;3.1. Bối Cảnh Bài Toán Nghiệp Vụ (Problem Statement)&quot;">​</a></h3><ul><li><strong>Tên hệ thống:</strong> Hệ thống hỗ trợ chẩn đoán, phân loại thể bệnh và quản lý điều trị Mày đay &amp; Phản vệ (Dr May Day v2.0).</li><li><strong>Đơn vị phối hợp chuyên môn:</strong> Bệnh viện Da liễu Trung ương &amp; Các viện nghiên cứu y tế thông minh.</li><li><strong>Đặc tính kỹ thuật cốt lõi:</strong><ol><li><em>Tính an toàn sinh mạng (Safety-critical):</em> Phải phát hiện phản vệ cấp cứu trong &lt; 30 giây bằng động cơ quy tắc cứng (Rule-based Engine), không phụ thuộc độ trễ mạng.</li><li><em>Đa phương thức (Multimodal):</em> Kết hợp ảnh chụp tổn thương sẩn phù từ smartphone của người bệnh với hồ sơ bệnh án điện tử (EHR) và 7 xét nghiệm biomarker sinh hóa.</li><li><em>Tải biến động lớn:</em> Hàng chục ngàn bệnh nhân tự chấm điểm UAS7 tại nhà vào buổi tối; bác sĩ hội chẩn đồng thời trên Web Dashboard.</li><li><em>Bảo mật và Quyền riêng tư:</em> Tuân thủ nghiêm ngặt Luật An toàn thông tin mạng và quy chuẩn bảo vệ dữ liệu sức khỏe cá nhân.</li></ol></li></ul><h3 id="_3-2-ban-đo-kien-truc-tong-quan-c4-model-level-1-system-context" tabindex="-1">3.2. Bản Đồ Kiến Trúc Tổng Quan (C4 Model - Level 1 System Context) <a class="header-anchor" href="#_3-2-ban-đo-kien-truc-tong-quan-c4-model-level-1-system-context" aria-label="Permalink to &quot;3.2. Bản Đồ Kiến Trúc Tổng Quan (C4 Model - Level 1 System Context)&quot;">​</a></h3>',23)),(n(),g(s,null,{default:h(()=>[l(i,{id:"mermaid-148",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20User%5B%22B%E1%BB%87nh%20nh%C3%A2n%20(Mobile%20App)%22%5D%0A%20%20%20%20Doctor%5B%22B%C3%A1c%20s%C4%A9%20Chuy%C3%AAn%20khoa%20(Web%20Portal)%22%5D%0A%20%20%20%20Admin%5B%22Qu%E1%BA%A3n%20tr%E1%BB%8B%20vi%C3%AAn%20Y%20t%E1%BA%BF%22%5D%0A%0A%20%20%20%20subgraph%20MayDaySystem%5B%22H%E1%BB%87%20Th%E1%BB%91ng%20Y%20T%E1%BA%BF%20S%E1%BB%91%20Th%C3%B4ng%20Minh%20Dr%20May%20Day%20v2.0%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22API%20Gateway%20%26%20Reverse%20Proxy%20(Kong%20%2F%20Envoy)%22%5D%0A%20%20%20%20%20%20%20%20CoreService%5B%22Core%20Medical%20Record%20Service%20(Modular%20Monolith)%22%5D%0A%20%20%20%20%20%20%20%20AIService%5B%22AI%20Vision%20%26%20UAS7%20Severity%20Service%20(Python%2FFastAPI)%22%5D%0A%20%20%20%20%20%20%20%20CDSSService%5B%22Clinical%20Decision%20Support%20%26%20Endotype%20Service%22%5D%0A%20%20%20%20%20%20%20%20Broker%5B%22Message%20Broker%20(RabbitMQ%20%2F%20Apache%20Kafka)%22%5D%0A%20%20%20%20%20%20%20%20Cache%5B%22Distributed%20Cache%20(Redis%20Cluster)%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(Primary%20DB%3A%20PostgreSQL%20%2B%20MinIO)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20EHR_Ext%5B%22H%E1%BB%87%20th%E1%BB%91ng%20B%E1%BB%87nh%20vi%E1%BB%87n%20(HIS%2FLIS)%22%5D%0A%20%20%20%20Push_Ext%5B%22H%E1%BA%A1%20t%E1%BA%A7ng%20Th%C3%B4ng%20b%C3%A1o%20(Firebase%20Cloud%20Messaging)%22%5D%0A%0A%20%20%20%20User%20--%3E%7C%22HTTPS%20%2F%20REST%20%2F%20WebSocket%22%7C%20API%0A%20%20%20%20Doctor%20--%3E%7C%22HTTPS%20%2F%20REST%22%7C%20API%0A%20%20%20%20Admin%20--%3E%7C%22Internal%20Admin%20Portal%22%7C%20API%0A%0A%20%20%20%20API%20--%3E%20CoreService%0A%20%20%20%20API%20--%3E%20AIService%0A%20%20%20%20API%20--%3E%20CDSSService%0A%0A%20%20%20%20CoreService%20%3C--%3E%7C%22Publish%2FSubscribe%20Events%22%7C%20Broker%0A%20%20%20%20AIService%20%3C--%3E%7C%22Consume%20Tasks%20%2F%20Publish%20Results%22%7C%20Broker%0A%20%20%20%20CDSSService%20%3C--%3E%20Broker%0A%0A%20%20%20%20CoreService%20%3C--%3E%20Cache%0A%20%20%20%20CoreService%20%3C--%3E%20DB%0A%20%20%20%20AIService%20%3C--%3E%20DB%0A%0A%20%20%20%20CoreService%20-.-%3E%7C%22HL7%20%2F%20FHIR%22%7C%20EHR_Ext%0A%20%20%20%20CoreService%20-.-%3E%7C%22Push%20Alert%22%7C%20Push_Ext%0A%0A%20%20%20%20style%20MayDaySystem%20fill%3A%23f8f9fa%2Cstroke%3A%2337474f%2Cstroke-width%3A2px%0A%20%20%20%20style%20API%20fill%3A%23fff9c4%2Cstroke%3A%23fbc02d%2Cstroke-width%3A2px%0A%20%20%20%20style%20AIService%20fill%3A%23e8f5e9%2Cstroke%3A%232e7d32%2Cstroke-width%3A2px%0A%20%20%20%20style%20Broker%20fill%3A%23ffe0b2%2Cstroke%3A%23f57c00%2Cstroke-width%3A2px%0A%20%20%20%20style%20DB%20fill%3A%23e1f5fe%2Cstroke%3A%230288d1%2Cstroke-width%3A2px%0A"})]),fallback:h(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p><em>Hình 0.1: Sơ đồ Ngữ cảnh Hệ thống (C4 Level 1 &amp; 2) của Case Study Dr May Day v2.0.</em></p><hr><h3 id="_3-3-ma-tran-đong-hanh-cua-case-study-qua-tung-chuong" tabindex="-1">3.3. Ma Trận Đồng Hành Của Case Study Qua Từng Chương <a class="header-anchor" href="#_3-3-ma-tran-đong-hanh-cua-case-study-qua-tung-chuong" aria-label="Permalink to &quot;3.3. Ma Trận Đồng Hành Của Case Study Qua Từng Chương&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Chương</th><th style="text-align:left;">Chủ đề Kỹ thuật</th><th style="text-align:left;">Sự tiến hóa cụ thể của Case Study Dr May Day v2.0</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Chương 1</strong></td><td style="text-align:left;">SDLC &amp; Agile/DevOps</td><td style="text-align:left;">Lập kế hoạch Sprint 2 tuần cho nhóm 6 kỹ sư xây dựng MVP; tính toán chỉ số DORA cho hệ thống.</td></tr><tr><td style="text-align:center;"><strong>Chương 2</strong></td><td style="text-align:left;">Yêu cầu &amp; Thiết kế C4</td><td style="text-align:left;">Viết User Story chuẩn cho tính năng &quot;Chấm điểm sẩn phù UAS7 tự động&quot;; vẽ sơ đồ C4 Container &amp; Component.</td></tr><tr><td style="text-align:center;"><strong>Chương 3</strong></td><td style="text-align:left;">OOP &amp; Clean Code</td><td style="text-align:left;">Hiện thực hóa Domain Model khám bệnh; áp dụng SOLID loại bỏ phụ thuộc cứng giữa tầng AI và bệnh án.</td></tr><tr><td style="text-align:center;"><strong>Chương 4</strong></td><td style="text-align:left;">Mẫu Thiết kế (GoF)</td><td style="text-align:left;">Cài đặt Factory Pattern chọn thuật toán phân vùng ảnh; Observer Pattern kích hoạt cảnh báo sốc phản vệ.</td></tr><tr><td style="text-align:center;"><strong>Chương 5</strong></td><td style="text-align:left;">Agile &amp; DevSecOps</td><td style="text-align:left;">Xây dựng Git Flow phân nhánh; thiết lập Pipeline GitHub Actions quét mã tĩnh SAST và lỗ hổng thư viện SCA.</td></tr><tr><td style="text-align:center;"><strong>Chương 6</strong></td><td style="text-align:left;">Microservices &amp; EDA</td><td style="text-align:left;">Di trú tính năng phân tích ảnh AI sang Microservice bằng Strangler Fig; phối hợp giao dịch bằng Saga Pattern.</td></tr><tr><td style="text-align:center;"><strong>Chương 7</strong></td><td style="text-align:left;">Kiểm thử Tự động &amp; CI/CD</td><td style="text-align:left;">Viết Unit Test cho công thức UAS7; dựng Mock Test giả lập Server bệnh viện; thiết lập TDD thực chiến.</td></tr><tr><td style="text-align:center;"><strong>Chương 8</strong></td><td style="text-align:left;">API REST &amp; Quản trị Data</td><td style="text-align:left;">Thiết kế REST API chuẩn hóa; cài đặt Cache-Aside với Redis chống tuyết lở (Cache Avalanche); phân mảnh bảng ảnh.</td></tr><tr><td style="text-align:center;"><strong>Chương 9</strong></td><td style="text-align:left;">AI-Augmented SE</td><td style="text-align:left;">Dùng LLM &amp; Agentic Coding (Claude Code) hỗ trợ sinh mã kiểm thử; xây dựng kịch bản RAG tra cứu phác đồ điều trị.</td></tr><tr><td style="text-align:center;"><strong>Chương 10</strong></td><td style="text-align:left;">MLOps &amp; Tích hợp AI</td><td style="text-align:left;">Đóng gói mô hình Vision đếm sẩn phù bằng ONNX; dựng pipeline giám sát độ trôi dữ liệu (Data Drift) sau triển khai.</td></tr><tr><td style="text-align:center;"><strong>Chương 11</strong></td><td style="text-align:left;">Bảo mật &amp; Observability</td><td style="text-align:left;">Mã hóa hồ sơ bệnh nhân theo chuẩn AES-256; tích hợp OpenTelemetry thu thập log và cảnh báo nghẽn hệ thống.</td></tr><tr><td style="text-align:center;"><strong>Chương 12</strong></td><td style="text-align:left;">Microfrontends &amp; Cross-Platform</td><td style="text-align:left;">Xây dựng ứng dụng di động cho bệnh nhân (chụp ảnh tổn thương) tích hợp với Dashboard quản trị Web của bác sĩ.</td></tr></tbody></table><hr><h2 id="_4-huong-dan-su-dung-sach-va-kho-ma-nguon-đi-kem" tabindex="-1">4. HƯỚNG DẪN SỬ DỤNG SÁCH VÀ KHO MÃ NGUỒN ĐI KÈM <a class="header-anchor" href="#_4-huong-dan-su-dung-sach-va-kho-ma-nguon-đi-kem" aria-label="Permalink to &quot;4. HƯỚNG DẪN SỬ DỤNG SÁCH VÀ KHO MÃ NGUỒN ĐI KÈM&quot;">​</a></h2><p>Mỗi chương trong cuốn sách được tổ chức nhất quán theo <strong>Cấu trúc SSoT 6 phần</strong>:</p><ol><li><strong>Mục tiêu học tập &amp; Khung năng lực</strong> (Định vị rõ giá trị độc giả thu được).</li><li><strong>Nội dung lý thuyết cốt lõi &amp; Sơ đồ khái niệm Mermaid</strong> (Trình bày bản chất toán học, kiến trúc và chuẩn mực).</li><li><strong>Nghiên cứu tình huống thực tế ngành (Real-world Case Study)</strong> (Gắn chặt với Dr May Day).</li><li><strong>Bài tập thực hành từng bước (Hands-on Lab)</strong> (Có đề bài, hướng dẫn code mẫu và tiêu chí nghiệm thu).</li><li><strong>Câu hỏi ôn tập &amp; Tình huống tranh luận phản biện</strong> (Giúp đào sâu bản chất thiết kế).</li><li><strong>Danh mục tài liệu tham khảo chuẩn mực</strong> (Trỏ chính xác vào kho <code>references/library.bib</code>).</li></ol><h3 id="kho-ma-nguon-thuc-hanh-repository" tabindex="-1">Kho Mã Nguồn Thực Hành (Repository) <a class="header-anchor" href="#kho-ma-nguon-thuc-hanh-repository" aria-label="Permalink to &quot;Kho Mã Nguồn Thực Hành (Repository)&quot;">​</a></h3><ul><li>Toàn bộ mã nguồn mẫu (TypeScript, Python, Dockerfile, GitHub Actions workflows) được lưu trữ tại kho mã nguồn của dự án.</li><li>Độc giả có thể clone mã nguồn, chạy thử nghiệm trên máy cá nhân bằng Docker Compose chỉ với một dòng lệnh:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ul><hr>',11))])}const S=a(u,[["render",d]]);export{b as __pageData,S as default};
